insert into content_pieces (id, kind, locale, author, body, media_url, virtues, temperaments, source, status) values ('l-ia', 'lesson', 'es', 'Alexandre Havard', '{"id":"l-ia","titulo":"4 principios para seguir siendo humano con la IA","autor":"Alexandre Havard","virtudes":["prudencia"],"intro":"La IA da respuestas en segundos, pero no puede deliberar, juzgar ni decidir por ti.","tarjetas":[{"titulo":"Verifica la información","texto":"Lo que te da la IA es lo estadísticamente probable, no la verdad. Antes de decidir, comprueba las fuentes."},{"titulo":"Escucha tu conciencia","texto":"Cada respuesta trae una lógica detrás. Tu conciencia ilumina el valor moral de cada opción, y puede sugerirte otras."},{"titulo":"Pide consejo","texto":"La IA no es un amigo que sabe y que siente. Pregunta a personas con experiencia y buen juicio."},{"titulo":"Asume la responsabilidad","texto":"Tus decisiones son tuyas. No las delegues en una máquina."}],"cierre":"No es un método: es una escuela de prudencia.","fuente":"Virtuous Leadership · 4 principios (resumen)"}', null, array['prudencia']::text[], array[]::text[], 'Virtuous Leadership · 4 principios (resumen)', 'draft') on conflict (id) do update set body = excluded.body, media_url = excluded.media_url;
insert into content_pieces (id, kind, locale, author, body, media_url, virtues, temperaments, source, status) values ('l-metodo', 'lesson', 'es', 'Virtuous Leadership', '{"id":"l-metodo","titulo":"El método en seis ideas","autor":"Virtuous Leadership","virtudes":[],"intro":"Lo esencial del sistema de Liderazgo Virtuoso.","tarjetas":[{"titulo":"Liderar es educar","texto":"Crecer haciendo crecer a los demás: sacar fuera la grandeza que hay en cada persona."},{"titulo":"Un llamado universal","texto":"No depende del cargo ni del temperamento. Está abierto a todos."},{"titulo":"Vocación y misión","texto":"La vocación es un llamado a ser; la misión, un llamado a hacer."},{"titulo":"Temperamento y carácter","texto":"Naces con tu temperamento; el carácter lo construyes libremente con las virtudes."},{"titulo":"Las virtudes del corazón","texto":"Magnanimidad y humildad son la esencia; prudencia, fortaleza, dominio de sí y justicia, el fundamento."},{"titulo":"Primero el corazón","texto":"Se crece contemplando la belleza de la virtud, discerniendo y actuando. Por eso importan los modelos."}],"cierre":"","fuente":"La contribución del sistema de Liderazgo Virtuoso (resumen)"}', null, array[]::text[], array[]::text[], 'La contribución del sistema de Liderazgo Virtuoso (resumen)', 'draft') on conflict (id) do update set body = excluded.body, media_url = excluded.media_url;
insert into test_definitions (id, version, kind, locale, status, definition) values ('temperamento-borrador', '0.1.0', 'temperament', 'es', 'draft', '{"id":"temperamento-borrador","kind":"temperament","version":"0.1.0","locale":"es","status":"draft","title":"Test de temperamento","intro":"Responde con tu primera reacción, la espontánea, no con la que te gustaría tener. No hay respuestas buenas ni malas: el temperamento no es virtud ni vicio. Elige la opción que más se parece a ti.","dimensions":["COL","MEL","SAN","FLE"],"items":[{"id":"t01","type":"choice","prompt":"Cuando surge un imprevisto que trastoca tu día, tu primera reacción es…","options":[{"id":"t01f","label":"Mantener la calma y esperar a ver cómo evoluciona","weights":{"FLE":1}},{"id":"t01m","label":"Inquietarte y pensar en lo que puede salir mal","weights":{"MEL":1}},{"id":"t01c","label":"Tomar el control y reorganizarlo todo enseguida","weights":{"COL":1}},{"id":"t01s","label":"Improvisar con buen humor y seguir adelante","weights":{"SAN":1}}]},{"id":"t02","type":"choice","prompt":"En una reunión o comida con varias personas, sueles…","options":[{"id":"t02m","label":"Escuchar mucho y hablar poco, observando","weights":{"MEL":1}},{"id":"t02s","label":"Animar la conversación y conectar con todos","weights":{"SAN":1}},{"id":"t02f","label":"Estar a gusto, sin necesidad de destacar","weights":{"FLE":1}},{"id":"t02c","label":"Llevar la conversación hacia lo que hay que decidir","weights":{"COL":1}}]},{"id":"t03","type":"choice","prompt":"Cuando alguien te lleva la contraria, lo primero que sientes es…","options":[{"id":"t03m","label":"Una herida que te dura y a la que das vueltas","weights":{"MEL":1}},{"id":"t03c","label":"Ganas de rebatir y defender tu postura","weights":{"COL":1}},{"id":"t03f","label":"Poca alteración; prefieres no discutir","weights":{"FLE":1}},{"id":"t03s","label":"Un enfado rápido que se te pasa pronto","weights":{"SAN":1}}]},{"id":"t04","type":"choice","prompt":"Ante una decisión importante, tiendes a…","options":[{"id":"t04f","label":"Posponerla mientras no sea urgente","weights":{"FLE":1}},{"id":"t04s","label":"Dejarte llevar por el entusiasmo del momento","weights":{"SAN":1}},{"id":"t04c","label":"Decidir rápido y corregir sobre la marcha","weights":{"COL":1}},{"id":"t04m","label":"Analizarlo todo y tardar en decidirte","weights":{"MEL":1}}]},{"id":"t05","type":"choice","prompt":"Lo que más te cuesta de un proyecto largo es…","options":[{"id":"t05s","label":"Mantener el interés cuando pasa la novedad","weights":{"SAN":1}},{"id":"t05c","label":"La lentitud de los demás","weights":{"COL":1}},{"id":"t05m","label":"Dar el primer paso sin tenerlo todo claro","weights":{"MEL":1}},{"id":"t05f","label":"Ponerte en marcha con energía","weights":{"FLE":1}}]},{"id":"t06","type":"choice","prompt":"Cuando recuerdas una ofensa, normalmente…","options":[{"id":"t06s","label":"Ya casi la has olvidado","weights":{"SAN":1}},{"id":"t06f","label":"No le diste demasiada importancia","weights":{"FLE":1}},{"id":"t06c","label":"La usas como acicate para actuar","weights":{"COL":1}},{"id":"t06m","label":"La recuerdas con detalle durante mucho tiempo","weights":{"MEL":1}}]},{"id":"t07","type":"choice","prompt":"En tu tiempo libre te atrae más…","options":[{"id":"t07m","label":"Un buen libro, música o soledad tranquila","weights":{"MEL":1}},{"id":"t07f","label":"Descansar sin prisas ni obligaciones","weights":{"FLE":1}},{"id":"t07s","label":"Un plan con gente y cosas nuevas","weights":{"SAN":1}},{"id":"t07c","label":"Un reto o algo que conquistar","weights":{"COL":1}}]},{"id":"t08","type":"choice","prompt":"Tus emociones, en general…","options":[{"id":"t08f","label":"Son suaves y estables","weights":{"FLE":1}},{"id":"t08c","label":"Son intensas y te empujan a actuar","weights":{"COL":1}},{"id":"t08s","label":"Son vivas pero pasajeras","weights":{"SAN":1}},{"id":"t08m","label":"Son profundas y duraderas","weights":{"MEL":1}}]},{"id":"t09","type":"choice","prompt":"Cuando trabajas en equipo, te sale de forma natural…","options":[{"id":"t09m","label":"Cuidar los detalles y la calidad","weights":{"MEL":1}},{"id":"t09s","label":"Crear buen ambiente y motivar","weights":{"SAN":1}},{"id":"t09c","label":"Organizar y repartir tareas","weights":{"COL":1}},{"id":"t09f","label":"Mediar y evitar tensiones","weights":{"FLE":1}}]},{"id":"t10","type":"choice","prompt":"Si un plan sale mal, tu primera reacción es…","options":[{"id":"t10m","label":"Pensar que quizá no estabas a la altura","weights":{"MEL":1}},{"id":"t10f","label":"Aceptarlo sin demasiado drama","weights":{"FLE":1}},{"id":"t10s","label":"Quitarle hierro y pasar a otra cosa","weights":{"SAN":1}},{"id":"t10c","label":"Buscar enseguida otra vía para lograrlo","weights":{"COL":1}}]},{"id":"t11","type":"choice","prompt":"Las personas que te conocen dirían que eres…","options":[{"id":"t11f","label":"Tranquilo y paciente","weights":{"FLE":1}},{"id":"t11c","label":"Decidido y exigente","weights":{"COL":1}},{"id":"t11m","label":"Reflexivo y sensible","weights":{"MEL":1}},{"id":"t11s","label":"Alegre y espontáneo","weights":{"SAN":1}}]},{"id":"t12","type":"choice","prompt":"Con la rutina diaria…","options":[{"id":"t12f","label":"Te encuentras cómodo","weights":{"FLE":1}},{"id":"t12m","label":"Te sientes seguro si está bien ordenada","weights":{"MEL":1}},{"id":"t12s","label":"Te aburres pronto y buscas variedad","weights":{"SAN":1}},{"id":"t12c","label":"Te impacientas si no avanza hacia una meta","weights":{"COL":1}}]},{"id":"t13","type":"choice","prompt":"Cuando debes hablar en público…","options":[{"id":"t13f","label":"Lo haces con sencillez, sin buscarlo","weights":{"FLE":1}},{"id":"t13s","label":"Disfrutas y te sale con naturalidad","weights":{"SAN":1}},{"id":"t13c","label":"Lo haces con aplomo, para convencer","weights":{"COL":1}},{"id":"t13m","label":"Lo preparas mucho y te inquieta","weights":{"MEL":1}}]},{"id":"t14","type":"choice","prompt":"Ante el sufrimiento de alguien cercano, tu primera reacción es…","options":[{"id":"t14m","label":"Sentirlo hondamente contigo","weights":{"MEL":1}},{"id":"t14f","label":"Acompañarle con calma y paciencia","weights":{"FLE":1}},{"id":"t14c","label":"Buscar una solución práctica","weights":{"COL":1}},{"id":"t14s","label":"Intentar animarle y distraerle","weights":{"SAN":1}}]},{"id":"t15","type":"choice","prompt":"Si tienes que esperar más de lo previsto…","options":[{"id":"t15m","label":"Empiezas a preocuparte","weights":{"MEL":1}},{"id":"t15f","label":"Esperas sin problema","weights":{"FLE":1}},{"id":"t15s","label":"Te pones a charlar o a hacer otra cosa","weights":{"SAN":1}},{"id":"t15c","label":"Te irritas y buscas cómo acelerar","weights":{"COL":1}}]},{"id":"t16","type":"choice","prompt":"Lo que más te mueve a actuar es…","options":[{"id":"t16c","label":"Conseguir un objetivo","weights":{"COL":1}},{"id":"t16m","label":"Hacer las cosas bien, con sentido","weights":{"MEL":1}},{"id":"t16s","label":"Compartir la experiencia con otros","weights":{"SAN":1}},{"id":"t16f","label":"La paz y la armonía","weights":{"FLE":1}}]}],"source":"BORRADOR de desarrollo. Se sustituirá por el banco y la puntuación oficiales del test de virtuousleadership.com."}'::jsonb) on conflict (id, version, locale) do update set definition = excluded.definition, status = excluded.status;
insert into test_definitions (id, version, kind, locale, status, definition) values ('caracter-borrador', '0.1.0', 'character', 'es', 'draft', '{"id":"caracter-borrador","kind":"character","version":"0.1.0","locale":"es","status":"draft","title":"Test de carácter","intro":"Piensa en las últimas semanas, no en cómo te gustaría ser. Quien crece en humildad se conoce con más verdad y a veces se puntúa más bajo: es buena señal.","dimensions":["magnanimidad","humildad","prudencia","fortaleza","dominio","justicia"],"likertScale":{"min":1,"max":5,"labels":["Nunca","Pocas veces","A veces","A menudo","Siempre"]},"items":[{"id":"mag1","type":"likert","prompt":"Me propongo metas grandes, a la medida de mis talentos.","promptOther":"Se propone metas grandes, a la medida de sus talentos.","dimension":"magnanimidad"},{"id":"mag2","type":"likert","prompt":"Me conformo con hacer lo justo.","promptOther":"Se conforma con hacer lo justo.","dimension":"magnanimidad","reverse":true},{"id":"mag3","type":"likert","prompt":"Pienso en cómo mi trabajo puede servir a algo más grande que yo.","promptOther":"Piensa en cómo su trabajo puede servir a algo más grande que él o ella.","dimension":"magnanimidad"},{"id":"hum1","type":"likert","prompt":"Reconozco mis errores sin justificarme.","promptOther":"Reconoce sus errores sin justificarse.","dimension":"humildad"},{"id":"hum2","type":"likert","prompt":"Busco que los demás crezcan, aunque no se note mi papel.","promptOther":"Busca que los demás crezcan, aunque no se note su papel.","dimension":"humildad"},{"id":"hum3","type":"likert","prompt":"Me molesta que otros reciban el mérito.","promptOther":"Le molesta que otros reciban el mérito.","dimension":"humildad","reverse":true},{"id":"pru1","type":"likert","prompt":"Antes de decidir, me informo y pido consejo.","promptOther":"Antes de decidir, se informa y pide consejo.","dimension":"prudencia"},{"id":"pru2","type":"likert","prompt":"Una vez deliberado, decido sin demorarme.","promptOther":"Una vez deliberado, decide sin demorarse.","dimension":"prudencia"},{"id":"pru3","type":"likert","prompt":"Decido según mi primera impresión.","promptOther":"Decide según su primera impresión.","dimension":"prudencia","reverse":true},{"id":"for1","type":"likert","prompt":"Me atrevo a hacer lo que debo aunque me dé miedo.","promptOther":"Se atreve a hacer lo que debe aunque le dé miedo.","dimension":"fortaleza"},{"id":"for2","type":"likert","prompt":"Mantengo mis compromisos aunque cueste.","promptOther":"Mantiene sus compromisos aunque cueste.","dimension":"fortaleza"},{"id":"for3","type":"likert","prompt":"Abandono cuando aparecen dificultades.","promptOther":"Abandona cuando aparecen dificultades.","dimension":"fortaleza","reverse":true},{"id":"dom1","type":"likert","prompt":"Sé decir que no a lo que me apetece cuando no conviene.","promptOther":"Sabe decir que no a lo que le apetece cuando no conviene.","dimension":"dominio"},{"id":"dom2","type":"likert","prompt":"Mi estado de ánimo marca mi manera de tratar a los demás.","promptOther":"Su estado de ánimo marca su manera de tratar a los demás.","dimension":"dominio","reverse":true},{"id":"dom3","type":"likert","prompt":"Pongo mis emociones al servicio de lo que es bueno.","promptOther":"Pone sus emociones al servicio de lo que es bueno.","dimension":"dominio"},{"id":"jus1","type":"likert","prompt":"Doy a cada uno lo que le corresponde, también a quien no me cae bien.","promptOther":"Da a cada uno lo que le corresponde, también a quien no le cae bien.","dimension":"justicia"},{"id":"jus2","type":"likert","prompt":"Cumplo mi palabra.","promptOther":"Cumple su palabra.","dimension":"justicia"},{"id":"jus3","type":"likert","prompt":"Trato mejor a quien me puede beneficiar.","promptOther":"Trata mejor a quien le puede beneficiar.","dimension":"justicia","reverse":true}],"source":"BORRADOR de desarrollo. Base definitiva: preguntas por virtud de Creados para la grandeza."}'::jsonb) on conflict (id, version, locale) do update set definition = excluded.definition, status = excluded.status;
